// @classlab exercise: Fix the average function
#include <iostream>
#include <iomanip>

double average(int total, int count) {
    return static_cast<double>(total) / count;
}

int main() {
    int n;
    std::cin >> n;
    int total = 0;
    for (int i = 0; i < n; ++i) {
        int score;
        std::cin >> score;
        total += score;
    }
    std::cout << std::fixed << std::setprecision(2) << average(total, n) << '\n';
}

