// @classlab exercise: Complete the score analyser
#include <iostream>

int total_score(const int scores[], int n) {
    int total = 0;
    for (int i = 0; i < n; ++i) total += scores[i];
    return total;
}

int maximum(const int scores[], int n) {
    int best = scores[0];
    for (int i = 1; i < n; ++i) if (scores[i] > best) best = scores[i];
    return best;
}

int count_passes(const int scores[], int n) {
    int passes = 0;
    for (int i = 0; i < n; ++i) if (scores[i] >= 60) ++passes;
    return passes;
}

int main() {
    int n;
    std::cin >> n;
    int scores[10] = {};
    for (int i = 0; i < n; ++i) std::cin >> scores[i];
    std::cout << total_score(scores, n) << ' ' << maximum(scores, n)
              << ' ' << count_passes(scores, n) << '\n';
}
